#include <stdio.h>
#include <math.h>
int main(){
    double points[3][2] = {{2,0},{0,2},{2,2}};
    double mu[2] = {0,0};
    for(int i=0;i<3;i++){
        mu[0] += points[i][0];
        mu[1] += points[i][1];
    }
    mu[0] /= 3.0; mu[1] /= 3.0;
    double Z[3][2];
    for(int i=0;i<3;i++){
        Z[i][0] = points[i][0] - mu[0];
        Z[i][1] = points[i][1] - mu[1];
    }
    // first principal component direction (1,-1)/sqrt(2)
    double v[2] = {1.0/sqrt(2.0), -1.0/sqrt(2.0)};
    for(int i=0;i<3;i++){
        double proj = Z[i][0]*v[0] + Z[i][1]*v[1];
        printf("%.3f\n", proj);
    }
    return 0;
}
